# Check reviewer post-to-director patterns to understand reviewer effectiveness
python3 << 'EOF'
import json, glob, os, re

# Get all unique reviewer sessions
files = glob.glob('/home/ubuntu/.claude-account-*/projects/*claude-sessions-reviewer*/*.jsonl')
unique = {}
for p in files:
    name = os.path.basename(p)
    if name not in unique or os.path.getsize(p) > os.path.getsize(unique[name]):
        unique[name] = p

print(f'Unique reviewer sessions: {len(unique)}')

# Find reviewer→director messages with key signals
critical_msgs = []
for p in unique.values():
    try:
        with open(p) as f:
            for line in f:
                try:
                    rec = json.loads(line)
                    msg = rec.get('message',{})
                    if not isinstance(msg, dict): continue
                    content = msg.get('content', [])
                    if not isinstance(content, list): continue
                    for c in content:
                        if isinstance(c, dict) and c.get('type')=='tool_use':
                            if 'reviewer_post' in c.get('name','').lower():
                                inp = c.get('input', {})
                                m = str(inp.get('message', inp.get('text', ''))) 
                                if 'critical' in m.lower() or 'bug' in m.lower() or '错误' in m or '不一致' in m:
                                    critical_msgs.append((rec.get('timestamp',''), m[:400]))
                except: pass
    except: pass

print(f'Reviewer critical/bug reports: {len(critical_msgs)}')
# Show a sample by date
critical_msgs.sort()
print('=== Early reviewer critical reports ===')
for ts, m in critical_msgs[:3]:
    print(f"\n[{ts[:16]}]\n{re.sub(chr(10),' ', m)[:400]}")
print('=== Late reviewer critical reports ===')
for ts, m in critical_msgs[-3:]:
    print(f"\n[{ts[:16]}]\n{re.sub(chr(10),' ', m)[:400]}")
